package main

import "testing"

func TestReportsDesignFactsOfProductionFilesOnly(t *testing.T) {
	report := inspected(t, map[string]string{
		"go.mod":               "module example.com/shop\n",
		"orders/cart.go":       "package orders\n\ntype Cart struct{ items []string }\n\nfunc (c *Cart) Lines() []string { return c.items }\n",
		"orders/cart_test.go":  "package orders\n\ntype Probe struct{}\n\nfunc (Probe) Run() {}\n",
		"orders/zz_gen.go":     "// Code generated by tool. DO NOT EDIT.\n\npackage orders\n\ntype Made struct{}\n\nfunc (Made) Run() {}\n",
		"orders/poll_linux.go": "package orders\n\ntype Poller struct{}\n\nfunc (Poller) Run() {}\n",
		"orders/broken.go":     "package orders\n\ntype Broken struct{}\n\nfunc (Broken) Run( {\n}\n",
	})
	var types []string
	for _, fact := range report.Design.Types {
		types = append(types, fact.ID)
	}
	if len(types) != 1 || types[0] != "orders/cart.go#Cart" {
		t.Fatalf("types %v", types)
	}
	lines := report.Design.Callables[0]
	if lines.ID != "orders/cart.go#Cart.Lines" || lines.ReturnsField != "items" {
		t.Fatalf("callables %+v", report.Design.Callables)
	}
}

func TestResolvesImportsThroughTheModulePath(t *testing.T) {
	report := inspected(t, map[string]string{
		"go.mod":          "module example.com/shop\n",
		"orders/cart.go":  "package orders\n\ntype Cart struct{ items []string }\n\nfunc (c *Cart) Lines() []string { return c.items }\n",
		"checkout/pay.go": "package checkout\n\nimport o \"example.com/shop/orders\"\n\nfunc Pay(c *o.Cart) {\n\tc.Lines()[0] = \"x\"\n}\n",
	})
	var pay []string
	for _, callable := range report.Design.Callables {
		for _, call := range callable.Calls {
			pay = append(pay, callable.ID+">"+call.Target+":"+call.Mutation)
		}
	}
	if len(pay) != 1 || pay[0] != "checkout/pay.go#Pay>orders/cart.go#Cart.Lines:assign" {
		t.Fatalf("calls %v", pay)
	}
}
